  `damage_school` tinyint NOT NULL DEFAULT '0',
  `armor` int unsigned NOT NULL DEFAULT '0',
  `melee_attack_power` int unsigned NOT NULL DEFAULT '0',
  `ranged_attack_power` int unsigned NOT NULL DEFAULT '0',
  `min_melee_dmg` float NOT NULL DEFAULT '0',
  `max_melee_dmg` float NOT NULL DEFAULT '0',
  `min_ranged_dmg` float NOT NULL DEFAULT '0',
  `max_ranged_dmg` float NOT NULL DEFAULT '0',
  `min_level_health` int unsigned NOT NULL DEFAULT '0',
  `max_level_health` int unsigned NOT NULL DEFAULT '0',
  `min_level_mana` int unsigned NOT NULL DEFAULT '0',
  `max_level_mana` int unsigned NOT NULL DEFAULT '0',
  `pet_spell_data_id` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
